#!/bin/sh
# packaging/deb/mk-copyright.sh -- GENERATOR for the runtime package's copyright file (PLAN 9.5).
#
#   packaging/deb/copyright is NOT a hand-written file. It is our header (PLAN 9.5, verbatim)
#   followed by the *content* of the pinned upstream debian/copyright, copied from the prepared
#   checkout -- not from a copy that lives in this repository. TASKS.md T3 requires exactly that
#   ("generated by concatenating the pinned upstream debian/copyright body under our header -- not
#   hand-written, so it cannot drift from the pin"), which is why this is a generator and not a
#   30-line file somebody will edit.
#
# The pin in the header's `Source:` field comes from upstream/manifest.json (the same file
# scripts/prepare.py checks out and scripts/build-packaging.sh builds). Never hard-coded here
# (it is a property of the pin).
#
# The upstream file's SHAPE decides how its content is copied, because the shipped file must
# have exactly one header paragraph (ours) and must stay a legal DEP-5 document:
#
#   * DEP-5 (first line is a `Format:` field): the upstream's own header paragraph is dropped
#     and everything from the first blank line on -- the per-directory Files:/Copyright:/License:
#     stanzas -- is appended byte-for-byte after our License paragraph. A DEP-5 file whose body
#     is empty FATALs: there would be no breakdown to copy (PLAN 9.5's fail-closed rule).
#   * NOT DEP-5 (the shape the pin ACTUALLY ships at 60ba801d: a flat `Copyright (C) ...`
#     notice per line, no Format: header, no stanzas -- runs 39245729525/39258643917 measured
#     the old assumption killing build-all's fail-fast before rpm/tar could run): the WHOLE
#     file is content, so it is copied in full as a continuation of our `Files: *` stanza's
#     Comment: field, each line indented by one space (leading and trailing blank lines
#     dropped). One space is the only transformation; a column-0 copy would start a malformed
#     paragraph. A file that holds no text at all FATALs in either shape.
#
# usage: mk-copyright.sh [--upstream FILE] [--out FILE] [--if-missing fail|note] [-h]
#
#   --upstream FILE        the pinned upstream debian/copyright to inline.
#                          Default: $UPSTREAM_COPYRIGHT, else <repo>/build/darling-src/debian/copyright
#   --out FILE             write here instead of stdout
#   --if-missing fail|note what to do when that file is absent (default: fail).
#                          `fail` is the only mode a real build may use: a package built without
#                          the pinned file would ship a copyright that silently lacks the
#                          upstream's own notices. `note` emits the header alone plus a
#                          `Comment:` continuation line saying so, and exists for `fixture`
#                          builds, which have no pinned checkout at all.
set -eu

dir=$(CDPATH='' cd -- "$(dirname -- "$0")" && pwd)
repo=$(CDPATH='' cd -- "$dir/../.." && pwd)
prog=${0##*/}

out=/dev/stdout
upstream=${UPSTREAM_COPYRIGHT:-$repo/build/darling-src/debian/copyright}
if_missing=fail

while [ "$#" -gt 0 ]; do
  case "$1" in
    --upstream) upstream=${2:?--upstream needs a file}; shift 2 ;;
    --out) out=${2:?--out needs a file}; shift 2 ;;
    --if-missing) if_missing=${2:?--if-missing needs fail|note}; shift 2 ;;
    -h | --help) sed -n '2,40p' "$0"; exit 0 ;;
    *) echo "$prog: FATAL unknown argument '$1'" >&2; exit 2 ;;
  esac
done

case "$if_missing" in
  fail | note) : ;;
  *) echo "$prog: FATAL --if-missing takes fail or note (got '$if_missing')" >&2; exit 2 ;;
esac

# The pin: the first 40-hex "revision" in the manifest -- the root component, i.e. the darling
# checkout that debian/copyright comes from. Never hard-coded here (it is a property of the pin).
pin=$(sed -n 's/.*"revision": "\([0-9a-fA-F]\{40\}\)".*/\1/p' "$repo/upstream/manifest.json" 2>/dev/null | head -n 1)
[ -n "$pin" ] || { echo "$prog: FATAL cannot read the upstream pin from $repo/upstream/manifest.json" >&2; exit 1; }

# is_dep5 FILE -- a DEP-5 document opens with its header paragraph, whose first line is the
# mandatory `Format:` field. Anything else (the real pinned file, for instance) is not one.
is_dep5() { head -n 1 -- "$1" | grep -q '^Format:'; }

# emit_header MODE -- the PLAN 9.5 header up to and including the `Files: *` stanza's Comment:
# field. MODE names the upstream shape the body will be: `breakdown` (the upstream stanzas
# follow below our License paragraph) or `verbatim` (the upstream's flat notice continues THIS
# field, so the sentence must not promise a per-directory breakdown that does not exist).
# The trailing License paragraph is emit_license_paragraph, so that the `verbatim` body can sit
# inside the stanza.
emit_header() {
  case $1 in
    breakdown | verbatim) : ;;
    *) echo "$prog: FATAL internal: unknown header mode '$1'" >&2; exit 1 ;;
  esac
  sed "s|@PIN@|$pin|" <<'HEADER'
Format: https://www.debian.org/doc/packaging-manuals/copyright-format/1.0/
Upstream-Name: darling
Upstream-Contact: https://www.darlinghq.org/
Source: https://github.com/darlinghq/darling
        (pinned at @PIN@, patched by darling-lol)

Files: *
Copyright: 2013-2026 Lubos Dolezel and the Darling contributors
           2026 darling-lol contributors
License: GPL-3.0-or-later
Comment: The guest tree under /usr/libexec/darling additionally contains code derived from
         Apple's open-source releases, under the Apple Public Source License 2.0, and
         third-party components under their own licenses. See
HEADER
  case $1 in
    breakdown)
      cat <<'MID'
         /usr/share/doc/darling-lol/copyright for the full per-directory breakdown, copied
         from the pinned upstream debian/copyright.
MID
      ;;
    verbatim)
      cat <<'MID'
         /usr/share/doc/darling-lol/copyright for the upstream copyright notices, copied
         verbatim from the pinned upstream debian/copyright. The pinned file is not a DEP-5
         document: it carries no Format: header and no per-directory Files: stanzas, so its
         full text continues this field below, each line indented by one space (leading and
         trailing blank lines dropped).
MID
      ;;
  esac
}

# emit_license_paragraph -- the header's second paragraph. The blank line that opens it is the
# paragraph separator, so the `verbatim` body must be emitted BEFORE this call.
emit_license_paragraph() {
  cat <<'TAIL'

License: GPL-3.0-or-later
 On Debian systems, the complete text of the GNU General Public License version 3
 can be found in "/usr/share/common-licenses/GPL-3".
TAIL
}

# emit_stanzas FILE -- everything from the first blank line on, verbatim. The header paragraph is
# dropped so that the result has exactly one header paragraph (ours).
emit_stanzas() {
  awk 'body { print } /^[[:space:]]*$/ { body = 1 }' "$1"
}

# emit_upstream_block FILE -- the whole file, each line indented by one space so it continues
# the Comment: field it is embedded in; leading and trailing blank lines dropped (a space-only
# line at the end of a field is legal but noise). Internal blank lines are kept: they belong to
# the copied content.
emit_upstream_block() {
  awk '
    { line[NR] = $0 }
    NF { if (!first) first = NR; last = NR }
    END { for (i = first; i <= last; i++) printf " %s\n", line[i] }
  ' "$1"
}

{
  if [ -r "$upstream" ]; then
    if is_dep5 "$upstream"; then
      if [ ! -s "$upstream" ] || [ -z "$(emit_stanzas "$upstream")" ]; then
        echo "$prog: FATAL $upstream has no stanzas after its header paragraph" >&2
        exit 1
      fi
      emit_header breakdown
      emit_license_paragraph
      printf '\n'
      emit_stanzas "$upstream"
    elif [ -n "$(tr -d '[:space:]' < "$upstream")" ]; then
      emit_header verbatim
      emit_upstream_block "$upstream"
      emit_license_paragraph
    else
      echo "$prog: FATAL $upstream holds no text at all: neither a DEP-5 header nor a copyright notice to copy" >&2
      exit 1
    fi
  elif [ "$if_missing" = note ]; then
    # a `Comment:` continuation line (a leading space), so the generated file stays a legal
    # DEP-5 document -- see the header of this script.
    emit_header breakdown
    emit_license_paragraph
    printf '         (upstream stanzas omitted: %s is absent in this build)\n' "$upstream"
  else
    echo "$prog: FATAL the pinned upstream copyright is missing: $upstream" >&2
    echo "$prog: run 'python3 scripts/prepare.py' first, or pass --upstream FILE." >&2
    echo "$prog: refusing to emit a copyright without the pinned upstream's notices (PLAN 9.5)." >&2
    exit 1
  fi
} > "$out"
